471	        refuseClosed(sheetId, claim.getDate());
472	        roles.require(sheetId, user, switch (to) {
473	            case OPEN -> "open";
474	            case SETTLED, PENDING -> "settle";
475	            case VOID -> "void";
476	            case DRAFT -> throw new IllegalStateException();
477	        });
478	        if (!claim.getStatus().canBecome(to)) {
479	            throw new ClaimStatusException(claim.getStatus(), to);
480	        }
481	        if (to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
482	            refuseVoidSettled(claim, sheetId, user);
483	        }
484	        String reversed = to == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED
485	                ? " reversed=" + show(claim.getSettledDue()) : "";
486	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
487	            throw new ClaimSettlerException();
488	        }
489	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
490	            throw new ClaimDeferException("The claim is deferred until " + claim.getDeferredUntil() + ".");
491	        }
492	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
493	                .orElseThrow(PersonNotFoundException::new);
494	        if (to == ClaimStatus.OPEN) {
495	            refuseNoteless(claim, shownDue(claim, person));
496	        }
497	        Rollup.Snapshot before = rollup.take(sheetId);
498	        String number = claim.getNumber();
499	        if (to == ClaimStatus.OPEN) {
500	            number = sheets.nextClaimNumber(sheetId, claim.getDate());
501	            claim.setOpenedBy(user);
502	        }
503	        if (to == ClaimStatus.SETTLED) {
504	            BigDecimal figure = claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
505	            BigDecimal due = figure == null ? null : charged(claim, figure);
506	            refuseUnproved(claim, due);
507	            if (overLimit(sheetId, user, due)) {
508	                to = ClaimStatus.PENDING;
509	            } else {
510	                claim.setSettledDue(due);
511	            }
512	        }
513	        claim.setStatus(to);
514	        claim.setNumber(number);
515	        logStatus(claim, person, user);
516	        Claim updated = claims.saveAndFlush(claim);
517	        String event = switch (to) {
518	            case OPEN -> "CLAIM_OPENED";
519	            case PENDING -> "CLAIM_PENDING";
520	            case SETTLED -> "CLAIM_SETTLED";
521	            case VOID -> "CLAIM_VOIDED";
522	            case DRAFT -> throw new IllegalStateException();
523	        };
524	        audit(event, updated, person, user, number, to == ClaimStatus.SETTLED ? dueField(updated) : reversed);
525	        if (to == ClaimStatus.SETTLED) {
526	            notifyWatchers(updated, person, user);
527	        }
528	        rollup.recordChanges(sheetId, user, before);
529	        return updated;
530	    }
