581	    /** Re-settle a SETTLED claim: freeze it again at the figure it would have today as an OPEN claim bound by
582	     *  no statement (today's rates, grades and floor, the late charge on the sheet's today on top). Refused
583	     *  unless the claim is SETTLED and the user is a steward, and for a claim in a closed period. */
584	    @Transactional
585	    public Claim resettle(String sheetId, String user, long claimId) {
586	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
