588	        if (!roles.isSteward(sheetId, user)) {
589	            throw new ClaimResettleException("Only a steward can re-settle a claim.");
590	        }
591	        if (claim.getStatus() != ClaimStatus.SETTLED) {
592	            throw new ClaimResettleException("Only a SETTLED claim can be re-settled.");
593	        }
594	        Rollup.Snapshot before = rollup.take(sheetId);
595	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
596	                .orElseThrow(PersonNotFoundException::new);
597	        BigDecimal old = claim.getSettledDue();
598	        BigDecimal figure = liveDue(claim, person);
599	        BigDecimal due = null;
600	        if (figure != null) {
601	            Sheet sheet = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new);
602	            due = claim.isCorrection() ? figure
603	                    : sheet.floored(figure.add(sheet.lateCharge(figure, claim.getDueBy(), claim.getDate())),
