673	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
674	        LocalDate on = date != null ? date : sheets.today(sheetId);
675	        refuseClosed(sheetId, claim.getDate());
676	        if (!roles.isSteward(sheetId, user)) {
677	            throw new ClaimRedateException("Only a steward can re-date a claim.");
678	        }
679	        if (!claim.getStatus().isOpen()) {
680	            throw new ClaimRedateException("Only an OPEN or PENDING claim can be re-dated.");
681	        }
682	        refuseClosed(sheetId, on);
683	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
684	                .orElseThrow(PersonNotFoundException::new);
