696	    /** Move a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its number and date,
697	     *  loses any figure a statement bound it to (live again until its new person's next statement), and is
698	     *  listed as its new person's newest claim. Refused unless the user's role may reassign, and for a settled or
699	     *  voided claim, a claim in a closed period, the claim's own person, or a person retired on its date. */
700	    @Transactional
701	    public Claim reassign(String sheetId, String user, long claimId, long toPersonId) {
702	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
703	        refuseClosed(sheetId, claim.getDate());
704	        if (!roles.allows(sheetId, user, "reassign")) {
705	            throw new ClaimReassignException("Your role may not reassign a claim.");
706	        }
707	        if (!claim.getStatus().canMove()) {
708	            throw new ClaimReassignException("A " + claim.getStatus() + " claim cannot be reassigned.");
709	        }
710	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
711	                .orElseThrow(PersonNotFoundException::new);
712	        Person to = people.findByIdAndSheetId(toPersonId, sheetId).orElseThrow(PersonNotFoundException::new);
713	        if (from.getId().equals(to.getId())) {
714	            throw new ClaimReassignException("The claim is already " + to.getName() + "'s.");
715	        }
716	        refuseRetired(to, claim.getDate());
717	        Rollup.Snapshot before = rollup.take(sheetId);
718	        claim.setPersonId(to.getId());
719	        claim.setStated(false, null);
720	        claim.setListOrder(claims.maxListOrder(sheetId) + 1);
721	        Claim updated = claims.saveAndFlush(claim);
722	        audit("CLAIM_REASSIGNED", updated, to, user, updated.getNumber(),
723	                " from=" + from.getName() + " to=" + to.getName());
724	        rollup.recordChanges(sheetId, user, before);
725	        return updated;
726	    }
