732	    /** Split an amount off an OPEN claim: the claim keeps the rest of its amount and loses any figure a
733	     *  statement bound it to; a new OPEN claim of the person with the amount split off, the same date and
734	     *  note, the next number, opened by the user and due by its date plus the terms in force on it, is
735	     *  listed as the sheet's newest, naming the original's number as split from. Refused unless the user's
736	     *  role may open a claim, the claim is OPEN and not deferred, and the amount is above 0.00 and below the
737	     *  claim's; and for a claim in a closed period. */
738	    @Transactional
739	    public Split split(String sheetId, String user, long claimId, BigDecimal amount) {
740	        Claim claim = claims.findForUpdateByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
741	        refuseClosed(sheetId, claim.getDate());
742	        roles.require(sheetId, user, "open");
743	        if (claim.getStatus() != ClaimStatus.OPEN) {
744	            throw new ClaimSplitException("Only an OPEN claim can be split.");
745	        }
746	        LocalDate today = sheets.today(sheetId);
747	        if (claim.deferredOn(today)) {
748	            throw new ClaimSplitException("The claim is deferred until " + claim.getDeferredUntil() + ".");
749	        }
750	        BigDecimal part = amount.setScale(2);
751	        if (part.signum() <= 0 || part.compareTo(claim.getAmount()) >= 0) {
752	            throw new ClaimSplitException("Split off more than 0.00 and less than the claim's amount.");
753	        }
754	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
755	                .orElseThrow(PersonNotFoundException::new);
756	        Rollup.Snapshot before = rollup.take(sheetId);
757	        claim.setAmount(claim.getAmount().subtract(part));
758	        claim.setStated(false, null);
759	        Claim kept = claims.saveAndFlush(claim);
760	        int terms = person.getTerms() != null ? person.getTerms()
761	                : sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new)
762	                        .termsFor(person.gradeOn(claim.getDate()), claim.getDate());
763	        Claim split = new Claim(sheetId, person.getId(), part, claim.getDate(), claim.getDate().plusDays(terms),
764	                claim.getNote(), null);
765	        split.setListOrder(claims.maxListOrder(sheetId) + 1);
766	        split.setStatus(ClaimStatus.OPEN);
767	        split.setNumber(sheets.nextClaimNumber(sheetId, claim.getDate()));
768	        split.setOpenedBy(user);
769	        split.setSplitFrom(claim.getNumber());
770	        logStatus(split, person, user);
771	        split = claims.saveAndFlush(split);
772	        audit("CLAIM_SPLIT", kept, person, user, kept.getNumber(), " into=" + split.getNumber());
773	        audit("CLAIM_OPENED", split, person, user);
774	        rollup.recordChanges(sheetId, user, before);
775	        return new Split(kept, split);
776	    }
