830	    /** The sheet's chosen claims in list order: people in the order they were added, each person's claims
831	     *  newest first. */
832	    private List<Claim> inListOrder(String sheetId, Set<Long> chosen) {
833	        Map<Long, Integer> personOrder = new HashMap<>();
834	        for (Person person : people.findBySheetIdOrderByIdAsc(sheetId)) {
835	            personOrder.put(person.getId(), personOrder.size());
836	        }
837	        return claims.findBySheetIdOrderByListOrderDesc(sheetId).stream()
838	                .filter(c -> chosen.contains(c.getId()))
839	                .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE)))
840	                .toList();
841	    }
