843	    /** A person, their statements in the order taken, and their claims newest first. */
844	    public record Stated(Person person, List<Statement> statements, List<Claim> claims) {
845	    }
846	
847	    /** Take a person's statement: record their due-total now (late charges included) and how many claims
848	     *  count, and bind each claim that counts to its rate figure now, under its late charge and floor (the charge is
849	     *  never bound: it keeps following the sheet's today, and the floor is applied on top; a PENDING claim is bound only once it is back to
850	     *  OPEN); a claim that does not count, is OPEN or PENDING and dated within one of its person's holds (or its person's retirement date is reached), or is
851	     *  deferred past the sheet's today, is left unbound. */
852	    @Transactional
853	    public Stated statement(String sheetId, String user, long personId) {
854	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
855	        LocalDate today = sheets.today(sheetId);
856	        List<Claim> theirs = claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, personId);
857	        Rollup.Snapshot before = rollup.take(sheetId);
858	        BigDecimal total = BigDecimal.ZERO.setScale(2);
859	        boolean figure = false;
860	        int counted = 0;
861	        for (Claim claim : theirs) {
862	            if (!claim.getStatus().counts() || (claim.getStatus().isOpen() && (person.heldOn(claim.getDate()) || person.retiredBy(today)))
863	                    || claim.deferredOn(today)) {
864	                claim.setStated(false, null);
865	                continue;
866	            }
867	            BigDecimal due = due(claim, person);
868	            if (due != null) {
869	                total = total.add(charged(claim, due));
870	                figure = true;
871	            }
872	            claim.setStated(true, due);
873	            counted++;
874	        }
875	        boolean rated = rates.findInForce(sheetId, person.gradeOn(today), today).isPresent();
876	        BigDecimal summed = total;
877	        BigDecimal dueTotal = rated || figure
878	                ? sheetRows.findById(sheetId).map(s -> s.capped(summed)).orElse(summed) : null;
879	        claims.saveAllAndFlush(theirs);
880	        statements.saveAndFlush(new Statement(sheetId, personId, today, dueTotal, counted));
881	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
882	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted);
883	        rollup.recordChanges(sheetId, user, before);
884	        return new Stated(person, statements.findByPersonIdOrderByIdAsc(personId), theirs);
885	    }
