887	    /** Take a person's statement as of a date on or before the sheet's today: the claims of theirs that
888	     *  counted at the end of that date (as the changes made while the sheet's today was on or before it left
889	     *  them; a later change does not count) are bound to their figures as they stood then, that date standing
890	     *  in for the sheet's today in every figure (the grade and rate in force, the floor, late charges, holds,
891	     *  retirements and the cap); every other claim of theirs is left unbound. The statement is dated that
892	     *  date. Refused for a date after the sheet's today, and one before the person was on the sheet. */
893	    @Transactional
894	    public Stated statementAsOf(String sheetId, String user, long personId, LocalDate asOf) {
895	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
896	        LocalDate today = sheets.today(sheetId);
897	        if (asOf.isAfter(today)) {
898	            throw new StatementRefusedException("A statement cannot be taken as of a date after the sheet's today ("
899	                    + today + ").");
900	        }
901	        Person then = history.findAsOf(Person.class, sheetId, personId, asOf)
902	                .orElseThrow(() -> new StatementRefusedException(person.getName() + " was not on the sheet on " + asOf + "."));
903	        Sheet sheetThen = history.findAsOf(Sheet.class, sheetId, sheetId, asOf).orElseGet(() -> {
904	            // no change to the sheet counts by then: it stands as it was started
905	            Sheet now = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new);
906	            return new Sheet(sheetId, now.getCreatedBy(), now.getCreatedAt(), asOf);
907	        });
908	        sheetThen.setToday(asOf);
909	        Optional<Sheet> onDate = Optional.of(sheetThen);
910	        List<Rate> ratesThen = history.listAsOf(Rate.class, sheetId, asOf);
911	        List<Claim> claimsThen = history.listAsOf(Claim.class, sheetId, asOf).stream()
912	                .filter(c -> c.getPersonId().equals(personId)).toList();
913	        List<Claim> theirs = claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, personId);
914	        Rollup.Snapshot before = rollup.take(sheetId);
915	        Map<Long, BigDecimal> figures = new HashMap<>();
916	        BigDecimal total = BigDecimal.ZERO.setScale(2);
917	        boolean figure = false;
918	        for (Claim claim : claimsThen) {
919	            if (!claim.getStatus().counts() || Rollup.heldOut(claim, then, asOf) || claim.deferredOn(asOf)) {
920	                continue;
921	            }
922	            BigDecimal due = claim.getSettledDue() != null ? claim.getSettledDue()
923	                    : claim.isBound() ? claim.getStatedDue()
924	                    : Rollup.inForce(ratesThen, then.gradeOn(claim.getDate()), claim.getDate())
925	                            .map(rate -> Rollup.rated(onDate, claim, claimsThen, rate)).orElse(null);
926	            if (due != null) {
927	                total = total.add(Rollup.charged(onDate, claim, due));
928	                figure = true;
929	            }
930	            figures.put(claim.getId(), due);
931	        }
932	        for (Claim claim : theirs) {
933	            claim.setStated(figures.containsKey(claim.getId()), figures.get(claim.getId()));
934	        }
935	        boolean rated = Rollup.inForce(ratesThen, then.gradeOn(asOf), asOf).isPresent();
936	        BigDecimal dueTotal = rated || figure ? sheetThen.capped(total) : null;
937	        int counted = figures.size();
938	        claims.saveAllAndFlush(theirs);
939	        statements.saveAndFlush(new Statement(sheetId, personId, asOf, dueTotal, counted));
940	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
941	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted
942	                + " asof=" + asOf);
943	        rollup.recordChanges(sheetId, user, before);
944	        return new Stated(person, statements.findByPersonIdOrderByIdAsc(personId), theirs);
945	    }
946	
947	    /** Cancel a person's last statement: the claims it bound are live again (a figure an earlier statement
948	     *  bound is not restored), and the statement before it becomes their last. Refused unless the user is a
949	     *  steward and the person has a statement. */
950	    @Transactional
951	    public Stated cancelStatement(String sheetId, String user, long personId) {
952	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
953	        if (!roles.isSteward(sheetId, user)) {
954	            throw new StatementCancelException("Only a steward can cancel a statement.");
955	        }
956	        List<Claim> theirs = claims.findForUpdateBySheetIdAndPersonIdOrderByListOrderDesc(sheetId, personId);
957	        List<Statement> taken = statements.findByPersonIdOrderByIdAsc(personId);
958	        if (taken.isEmpty()) {
959	            throw new StatementCancelException(person.getName() + " has no statement to cancel.");
960	        }
961	        Statement last = taken.get(taken.size() - 1);
962	        Rollup.Snapshot before = rollup.take(sheetId);
963	        for (Claim claim : theirs) {
964	            claim.setStated(false, null);
965	        }
966	        claims.saveAllAndFlush(theirs);
967	        statements.delete(last);
968	        statements.flush();
969	        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
970	                + " due-total=" + (last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString()));
971	        rollup.recordChanges(sheetId, user, before);
972	        return new Stated(person, statements.findByPersonIdOrderByIdAsc(personId), theirs);
973	    }
974	
975	    /** Refuse an edit of a claim whose editor another user has open. */
976	    private void refuseLocked(Claim claim, String user) {
977	        if (claim.getLockedBy() != null && !claim.getLockedBy().equals(user)) {
978	            throw new ClaimLockedException(claim.getLockedBy());
979	        }
980	    }
981	
982	    /** Refuse a change to a claim dated inside a closed period. Locks the sheet first, so a period being
983	     *  closed at the same moment is seen. */
984	    private void refuseClosed(String sheetId, LocalDate date) {
985	        sheetRows.findForUpdateById(sheetId).orElseThrow(SheetNotFoundException::new);
986	        if (periods.closedOn(sheetId, date)) {
987	            throw new PeriodClosedException();
988	        }
989	    }
990	
991	    /** Refuse voiding a SETTLED claim unless the user is a steward and the sheet's today is within 7 days
992	     *  of the date its status log last records it SETTLED. */
993	    private void refuseVoidSettled(Claim claim, String sheetId, String user) {
994	        if (!roles.isSteward(sheetId, user)) {
995	            throw new ClaimVoidException("Only a steward can void a settled claim.");
996	        }
997	        LocalDate settledOn = claim.getStatusLog().stream()
998	                .filter(line -> line.getStatus() == ClaimStatus.SETTLED)
999	                .map(StatusChange::getOn)
1000	                .reduce((first, last) -> last)
1001	                .orElse(null);
1002	        if (settledOn == null || sheets.today(sheetId).isAfter(settledOn.plusDays(7))) {
1003	            throw new ClaimVoidException("A settled claim can only be voided within 7 days of settling it.");
1004	        }
1005	    }
1006	
1007	    /** Refuse settling or approving a claim with no proof whose due is above the proof threshold in force on
1008	     *  its date; a due of n/a, or no threshold then, needs none. */
1009	    private void refuseUnproved(Claim claim, BigDecimal due) {
1010	        BigDecimal threshold = sheetRows.findById(claim.getSheetId()).orElseThrow(SheetNotFoundException::new)
1011	                .proofThresholdOn(claim.getDate());
1012	        if (threshold != null && due != null && due.compareTo(threshold) > 0 && claim.getProofs() == 0) {
1013	            throw new ClaimProofException("The claim's due is above the proof threshold: add a proof first.");
1014	        }
1015	    }
1016	
1017	    /** Refuse opening a claim with an empty note whose due is above the note threshold in force on its date;
1018	     *  a due of n/a, or no threshold then, needs none. */
1019	    private void refuseNoteless(Claim claim, BigDecimal due) {
1020	        BigDecimal threshold = sheetRows.findById(claim.getSheetId()).orElseThrow(SheetNotFoundException::new)
1021	                .noteThresholdOn(claim.getDate());
1022	        if (threshold != null && due != null && due.compareTo(threshold) > 0
1023	                && (claim.getNote() == null || claim.getNote().isBlank())) {
1024	            throw new ClaimNoteException("The claim's due is above the note threshold: give it a note first.");
1025	        }
1026	    }
1027	
1028	    /** Whether a clerk is settling a due above the sheet's clerk limit; a steward settles anything, and a
1029	     *  due of n/a, or a sheet with no limit, is within it. */
1030	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
1031	        BigDecimal limit = sheetRows.findById(sheetId).orElseThrow(SheetNotFoundException::new).getClerkLimit();
1032	        return limit != null && due != null && due.compareTo(limit) > 0 && !roles.isSteward(sheetId, user);
1033	    }
1034	
1035	    /** Refuse a negative amount that does not name a SETTLED claim of the person by number, and a claim of
1036	     *  0.00 or more that names one. */
1037	    private void refuseCorrection(String sheetId, long personId, BigDecimal amount, String corrects) {
1038	        if (amount.signum() >= 0) {
1039	            if (corrects != null) {
1040	                throw new ClaimCorrectionException("Only a negative amount corrects a claim.");
1041	            }
1042	            return;
1043	        }
1044	        if (corrects == null) {
1045	            throw new ClaimCorrectionException(
1046	                    "A negative amount is a correction: name the number of the settled claim it corrects.");
1047	        }
1048	        if (!claims.existsBySheetIdAndPersonIdAndNumberAndStatus(sheetId, personId, corrects, ClaimStatus.SETTLED)) {
1049	            throw new ClaimCorrectionException("A correction must name a settled claim of the same person.");
1050	        }
1051	    }
1052	
1053	    /** Refuse a claim dated after its person's retirement date. */
1054	    private static void refuseRetired(Person person, LocalDate date) {
1055	        if (person.retiredOn(date)) {
1056	            throw new PersonRetiredException();
1057	        }
1058	    }
1059	
1060	    /** A claim's figure: the due fixed when settled, else the one its last statement bound (not while
1061	     *  PENDING), else its live due; none when that is n/a. */
1062	    private BigDecimal due(Claim claim, Person person) {
1063	        if (claim.getSettledDue() != null) {
1064	            return claim.getSettledDue();
1065	        }
1066	        return claim.isBound() ? claim.getStatedDue() : liveDue(claim, person);
1067	    }
1068	
1069	    /** Log the status a claim has just taken: by the user, on the sheet's today, with its due as the
1070	     *  screen shows it now. */
1071	    private void logStatus(Claim claim, Person person, String user) {
1072	        claim.logStatus(user, sheets.today(claim.getSheetId()), shownDue(claim, person));
1073	    }
1074	
1075	    /** A claim's due as the screen shows it: fixed when settled, else its figure (bound or live) with its
1076	     *  late charge on top; none when that is n/a. */
1077	    private BigDecimal shownDue(Claim claim, Person person) {
1078	        if (claim.getSettledDue() != null) {
1079	            return claim.getSettledDue();
1080	        }
1081	        BigDecimal figure = due(claim, person);
1082	        return figure == null ? null : charged(claim, figure);
1083	    }
1084	
1085	    /** A claim's due from its figure: its late charge on the sheet's today on top while it is OPEN or
1086	     *  PENDING, then at least the floor in force on its date (a correction has neither). */
1087	    private BigDecimal charged(Claim claim, BigDecimal figure) {
1088	        return Rollup.charged(sheetRows.findById(claim.getSheetId()), claim, figure);
1089	    }
1090	
1091	    /** The claim's rate figure: its amount at the rate in force on its date of its person's grade in force
1092	     *  then, before any late charge or floor; none when no rate applies. */
1093	    private BigDecimal liveDue(Claim claim, Person person) {
1094	        Sheet sheet = sheetRows.findById(claim.getSheetId()).orElseThrow(SheetNotFoundException::new);
1095	        RoundingMode rounding = sheet.rounding(roundingDate(claim));
1096	        return rates.findInForce(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate())
1097	                .map(rate -> due(claim.getAmount(), rate, rounding))
1098	                .orElse(null);
1099	    }
1100	
1101	    /** The date a claim's figures round by: its own, or for a correction the date of the claim it corrects. */
1102	    private LocalDate roundingDate(Claim claim) {
1103	        if (!claim.isCorrection()) {
1104	            return claim.getDate();
1105	        }
1106	        return claims.findBySheetIdAndPersonIdAndNumber(claim.getSheetId(), claim.getPersonId(), claim.getCorrects())
1107	                .map(Claim::getDate).orElse(claim.getDate());
1108	    }
1109	
1110	    /** An amount times a rate, divided by 100, rounded to cents. */
1111	    private static BigDecimal due(BigDecimal amount, Rate rate, RoundingMode rounding) {
1112	        return amount.multiply(rate.getRate()).movePointLeft(2).setScale(2, rounding);
1113	    }
1114	
1115	    /** The due a settled claim was fixed at, as its audit line ends: n/a when it has none. */
1116	    private static String dueField(Claim claim) {
1117	        return " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
1118	    }
1119	
1120	    /** A due as an audit line shows it: n/a when there is none. */
1121	    private static String show(BigDecimal due) {
1122	        return due == null ? "n/a" : due.toPlainString();
1123	    }
1124	
1125	    /** Tell each user watching the claim's person, in the order they started watching. */
1126	    private void notifyWatchers(Claim claim, Person person, String user) {
1127	        for (Watch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
1128	            audit.recordOnCommit("NOTIFY sheet=" + claim.getSheetId() + " by=" + user + " user=" + watch.getUser()
1129	                    + " person=" + person.getName() + " number=" + claim.getNumber());
1130	        }
1131	    }
1132	
1133	    /** The amount as the screen shows it (two decimals), the date YYYY-MM-DD. */
1134	    private void audit(String event, Claim claim, Person person, String user) {
1135	        audit(event, claim, person, user, claim.getNumber(), "");
1136	    }
1137	
1138	    /** A claim with a number (a voided claim keeps its own) follows its date with number=, then any extra fields. */
1139	    private void audit(String event, Claim claim, Person person, String user, String number, String extra) {
1140	        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
1141	                + " person=" + person.getName() + " amount=" + claim.getAmount().toPlainString()
1142	                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
1143	    }
1144	}
